<script setup lang="ts">import {onMounted,ref} from 'vue';import {useRoute} from 'vue-router';import {AgGridVue} from 'ag-grid-vue3';import {api,messageOf} from '@/lib/api';import StatusBadge from '@/components/StatusBadge.vue';const id=String(useRoute().params.id),version=ref<any>(),rows=ref<any[]>([]),issues=ref<any[]>([]),tab=ref('entries'),search=ref(''),editing=ref<any>(),error=ref('');const cols=[{field:'ncm',headerName:'NCM',width:120},{field:'ex_code',headerName:'EX',width:80},{field:'description',headerName:'Descrição',flex:1,minWidth:300},{field:'expected_cst',headerName:'CST',width:90},{field:'expected_cclass_trib',headerName:'cClassTrib',width:120},{field:'reduction_type',headerName:'Redução',width:160},{field:'status',headerName:'Status',width:110},{field:'source_row',headerName:'Linha origem',width:110}];const issueCols=[{field:'severity',headerName:'Severidade',width:120},{field:'code',headerName:'Código',width:220},{field:'message',headerName:'Mensagem',flex:1},{field:'source_row',headerName:'Linha',width:100}];async function load(){version.value=(await api.get(`/catalogs/${id}`)).data;await query();issues.value=(await api.get(`/catalogs/${id}/issues`)).data.data}async function query(){rows.value=(await api.get(`/catalogs/${id}/entries`,{params:{search:search.value||undefined,per_page:500}})).data.data}onMounted(load);function edit(e:any){if(version.value.status==='published')return;editing.value={...e.data}}function add(){editing.value={ncm:'',ex_code:'',description:'',expected_cst:'',expected_cclass_trib:'',reduction_type:'',conditions:{}}}async function save(){error.value='';try{const url=editing.value.id?`/catalogs/${id}/entries/${editing.value.id}`:`/catalogs/${id}/entries`;await api.request({url,method:editing.value.id?'patch':'post',data:editing.value});editing.value=null;await query()}catch(e){error.value=messageOf(e)}}async function publish(){if(!confirm('Publicar esta versão e substituir a atualmente ativa?'))return;try{version.value=(await api.post(`/catalogs/${id}/publish`)).data}catch(e){alert(messageOf(e))}}async function revision(){const v=prompt('Versão da nova revisão:');if(!v)return;const {data}=await api.post(`/catalogs/${id}/revision`,{version:v});location.href=`/catalogos/${data.id}`}</script><template><section class="card hero" v-if="version"><div><div class="eyebrow">Catálogo fiscal versionado</div><h2>{{version.name}}</h2><p>{{version.version}} · {{version.ncm_entries_count}} parâmetros · {{version.issues_count}} críticas de importação</p></div><div class="actions"><StatusBadge :value="version.status"/><button v-if="version.status==='published'" @click="revision">Criar revisão editável</button><button v-else class="primary" @click="publish">Publicar</button></div></section><div class="tabs"><button :class="{active:tab==='entries'}" @click="tab='entries'">Parametrizações</button><button :class="{active:tab==='issues'}" @click="tab='issues'">Qualidade da fonte</button></div><section class="card" v-show="tab==='entries'"><div class="toolbar"><input v-model="search" @keyup.enter="query" placeholder="Buscar NCM ou descrição"/><button @click="query">Buscar</button><button v-if="version?.status!=='published'" class="primary" @click="add">Novo parâmetro</button></div><AgGridVue theme="legacy" class="ag-theme-quartz grid tall" :rowData="rows" :columnDefs="cols" :pagination="true" :paginationPageSize="100" @rowDoubleClicked="edit"/><p class="hint">Versões publicadas são imutáveis. Crie uma revisão para editar.</p></section><section class="card" v-show="tab==='issues'"><AgGridVue theme="legacy" class="ag-theme-quartz grid" :rowData="issues" :columnDefs="issueCols"/></section><div class="modal-backdrop" v-if="editing"><form class="modal form-grid" @submit.prevent="save"><h2 class="span-2">Parâmetro NCM × ClassTrib</h2><label>NCM<input v-model="editing.ncm" pattern="\d{8}" required/></label><label>EX<input v-model="editing.ex_code"/></label><label class="span-2">Descrição<input v-model="editing.description" required/></label><label>CST esperado<input v-model="editing.expected_cst" pattern="\d{3}"/></label><label>cClassTrib esperada<input v-model="editing.expected_cclass_trib" pattern="\d{6,12}"/></label><label class="span-2">Redução<input v-model="editing.reduction_type"/></label><p class="error span-2" v-if="error">{{error}}</p><div class="actions span-2"><button type="button" @click="editing=null">Cancelar</button><button class="primary">Salvar</button></div></form></div></template>
